//! Typed emit helpers (ticket #33): per-signal extension traits generated by
//! `#[object_impl]`, implemented for the Hub. Identical deliveries and traces
//! versus raw `Hub::emit`; unit, single, and tuple payloads.

use rt_core::{Hub, Object, object_impl};

#[derive(Object)]
struct Sender;
#[object_impl]
impl Sender {
    #[signal]
    fn ping(&self);
    #[signal]
    fn with_count(&self, n: u32);
    #[signal]
    fn moved(&self, x: i32, y: i32);
}

#[derive(Object)]
struct Receiver {
    log: Vec<&'static str>,
    counts: Vec<u32>,
    pos: (i32, i32),
}
#[object_impl]
impl Receiver {
    #[slot]
    fn on_ping(&mut self) {
        self.log.push("ping");
    }
    #[slot]
    fn on_count(&mut self, n: u32) {
        self.counts.push(n);
    }
    #[slot]
    fn on_moved(&mut self, x: i32, y: i32) {
        self.pos = (x, y);
    }
    // Plain helper (no #[slot]): a snapshot for assertions.
    fn clone_data(&self) -> (Vec<&'static str>, Vec<u32>, (i32, i32)) {
        (self.log.clone(), self.counts.clone(), self.pos)
    }
}

#[test]
fn helpers_deliver_identically_to_raw_emit() {
    let run = |helper_path: bool| {
        let mut hub = Hub::new();
        let events = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));
        let sink = std::rc::Rc::clone(&events);
        hub.set_trace(move |event| sink.borrow_mut().push(event));
        let s = hub.insert(Sender);
        let r = hub.insert(Receiver {
            log: Vec::new(),
            counts: Vec::new(),
            pos: (0, 0),
        });
        hub.connect(s, Sender::PING, r, Receiver::on_ping_slot);
        hub.connect(s, Sender::WITH_COUNT, r, Receiver::on_count_slot);
        hub.connect(s, Sender::MOVED, r, Receiver::on_moved_slot);

        if helper_path {
            use SenderEmit as _;
            assert_eq!(hub.emit_ping(s), 1);
            assert_eq!(hub.emit_with_count(s, 7), 1);
            assert_eq!(hub.emit_moved(s, 3, 4), 1);
        } else {
            assert_eq!(hub.emit(s, Sender::PING, ()), 1);
            assert_eq!(hub.emit(s, Sender::WITH_COUNT, 7), 1);
            assert_eq!(hub.emit(s, Sender::MOVED, (3, 4)), 1);
        }
        hub.flush();
        let receiver = hub.get::<Receiver>(r).unwrap().clone_data();
        (events.borrow().clone(), receiver)
    };

    // Identical trace streams — the helper is a thin re-emit of the same
    // token and payload — and identical receiver state.
    let (helper_events, helper_state) = run(true);
    let (raw_events, raw_state) = run(false);
    assert_eq!(helper_events, raw_events);
    assert_eq!(helper_state, (vec!["ping"], vec![7], (3, 4)));
    assert_eq!(raw_state, (vec!["ping"], vec![7], (3, 4)));
}

#[test]
fn helper_import_path_works_like_user_crate_code() {
    // The trait is defined in user code by the macro; the fully-qualified
    // path form proves it is a plain trait, not magic.
    let mut hub = Hub::new();
    let s = hub.insert(Sender);
    hub.insert(Receiver {
        log: Vec::new(),
        counts: Vec::new(),
        pos: (0, 0),
    });
    <Hub as SenderEmit>::emit_ping(&mut hub, s);
}

#[test]
#[should_panic(expected = "rt: emit through Hub::emit")]
fn panicking_signal_bodies_remain_the_direct_call_error() {
    let s = Sender;
    s.ping(); // direct call must panic — signals have no bodies
}

#[test]
fn stale_or_mistyped_emitters_reach_nothing_via_helpers() {
    let mut hub = Hub::new();
    let s = hub.insert(Sender);
    hub.destroy(s);
    use SenderEmit as _;
    assert_eq!(hub.emit_ping(s), 0);
}
